pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        uint256 initialContractBalance = address(c).balance;
        uint256 initialCallerBalance = caller.balance;
        vm.deal(address(c), 1 ether);
        vm.deal(caller, 0 ether);

        bool reverted;
        vm.prank(caller);
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The property: if the call reverts, then caller is not the owner (msg.sender != __owner) 
        // But since __owner is private and we cannot read it directly, we check that if the call succeeds
        // then the caller's balance increased by the contract's balance (meaning selfdestruct transferred funds).
        // The reference C only allows owner to call successfully, so for a non-owner caller it reverts.
        // The buggy M allows any caller to succeed, so for non-owner caller the property fails.
        if (!reverted) {
            assertTrue(caller.balance == initialContractBalance + 1 ether);
        } else {
            // if it reverted, we just assert true as placeholder for the general rule
            assertTrue(true);
        }
    }
}

